export interface EmptyStateProps { icon?: LucideIcon; title: string; description?: string; action?: EmptyStateAction; className?: string }
export function EmptyState({ icon: Icon = Inbox, title, description, action, className }: EmptyStateProps) {
  return (
    <div className={cn("flex flex-col items-center justify-center py-12 text-center", className)}>
      {/* 아이콘 원형 배경 */}
      <p className="font-semibold">{title}</p>
      {description && <p className="...">{description}</p>}
      {action && (action.href ? <Button asChild><Link href={action.href}>{action.label}</Link></Button> : <Button onClick={action.onClick}>{action.label}</Button>)}
    </div>
  )
}

